  ['tar', 3, 'Son 30 gün', 'Referans tarih 2024-12-31 olsun. Son 30 günde (2024-12-02 ve sonrası) verilen sipariş sayısı: <code>adet</code>.', "SELECT COUNT(*) AS adet FROM orders WHERE order_date >= date('2024-12-31', '-29 days');"]
